// Manifests
/// The lines of `cs`, in order, the current one so far `line`, its
/// characters newest first.
pub fn lines_from(mut cs: Chars, mut line: Chars) -> Strings {
    loop {
        if null_p(cs) {
            if null_p(line) {
                return nil::<Str>();
            } else {
                return kayak_rt::heap_cons(rev_to_string(line), kayak_rt::nil());
            }
        } else if char_eq_p(car(cs), '\n') {
            return kayak_rt::heap_cons(rev_to_string(line), lines_from(cdr(cs), nil::<char>()));
        } else {
            (cs, line) = (cdr(cs), kayak_rt::heap_cons(car(cs), line));
            continue;
        }
    }
}

pub fn drop_space(mut cs: Chars) -> Chars {
    loop {
        if (not(null_p(cs)) && char_whitespace_p(car(cs))) {
            cs = cdr(cs);
            continue;
        } else {
            return cs;
        }
    }
}

#[inline]
pub fn line_trimmed(s: Str) -> Str {
    rev_to_string(drop_space(rev_onto(drop_space(string_chars(s)), nil::<char>())))
}

