pub fn reverse_log(mut xs: Log<'static>, mut acc: Log<'static>) -> Log<'static> {
    loop {
        if null_p(xs) {
            return acc;
        } else {
            (xs, acc) = (cdr(xs), kayak_rt::heap_cons(car(xs), acc));
            continue;
        }
    }
}

